import { Catch, RpcExceptionFilter, ArgumentsHost } from '@nestjs/common';
import { Observable, throwError } from 'rxjs';
import { RpcException } from '@nestjs/microservices';

@Catch(RpcException)
export class ExceptionFilter implements RpcExceptionFilter<RpcException> {
  catch(exception: RpcException, host: ArgumentsHost): Observable<any> {
    return throwError(() => exception.getError());
  }
}

@Controller()
export class MathController {
  @UseFilters(new ExceptionFilter())
  @MessagePattern({ cmd: 'sum' })
  accumulate(data: number[]): number {
    if (!data) throw new RpcException('Invalid credentials.');
    return data.reduce((a, b) => a + b);
  }
}

@Controller()
export class MathController {
  @UsePipes(
    new ValidationPipe({
      exceptionFactory: (errors) => new RpcException(errors),
    }),
  )
  @MessagePattern({ cmd: 'sum' })
  accumulate(@Payload() data: number[]): number {
    return (data || []).reduce((a, b) => a + b, 0);
  }
}

import { z } from 'zod';
import { StandardSchemaValidationPipe } from '@nestjs/common';
import { RpcException } from '@nestjs/microservices';

const sumSchema = z.array(z.number());

@Controller()
export class MathController {
  @UsePipes(
    new StandardSchemaValidationPipe({
      exceptionFactory: (issues) => new RpcException(issues),
    }),
  )
  @MessagePattern({ cmd: 'sum' })
  accumulate(@Payload({ schema: sumSchema }) data: number[]): number {
    return data.reduce((a, b) => a + b, 0);
  }
}

import { Observable } from 'rxjs';
import { AsyncLocalStorage } from 'node:async_hooks';
import { randomUUID } from 'node:crypto';

export const als = new AsyncLocalStorage<{ correlationId: string }>();

const app = await NestFactory.createMicroservice<MicroserviceOptions>(
  AppModule,
  { transport: Transport.TCP },
);

app.registerPreRequestHook((ctx, next) => {
  return new Observable((subscriber) => {
    als.run({ correlationId: randomUUID() }, () => {
      next().subscribe(subscriber);
    });
  });
});

await app.listen();

app.registerPreRequestHook((ctx, next) => {
  const handler = ctx.getHandler().name;
  const start = Date.now();

  return next().pipe(
    tap(() => console.log(`[${handler}] completed in ${Date.now() - start}ms`)),
    catchError((err) => {
      console.error(`[${handler}] failed:`, err.message);
      return throwError(() => err);
    }),
  );
});

